        throw new IllegalArgumentException("Bucket cannot be null");
    }
    if (bucket == this) {
        throw new IllegalArgumentException("Cannot insert a bucket before itself");
    }
    Bucket prev = bucket.prev;
    this.prev = prev;
    this.next = bucket;
    bucket.prev = this;
    if (prev != null) {
        prev.next = this;
    } else {
        // bucket was the head
        head = this;
