static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    // Extract year, month, day from timeBucket
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Validate month and day
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month: " + month);
    }
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid day: " + day);
    }

    // Calculate the day of the year
    int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    // Check for leap year
    boolean isLeapYear = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    if (isLeapYear) {
        daysInMonth[1] = 29;
    }

    int dayOfYear = 0;
    for (int i = 0; i < month - 1; i++) {
        dayOfYear += daysInMonth[i];
    }
    dayOfYear += day;

    // Calculate the bucket start day of year
    // The bucket index is (dayOfYear - 1) / dayStep
    // The start day of the bucket is bucketIndex * dayStep + 1
    int bucketIndex = (dayOfYear - 1) / dayStep;
    int bucketStartDayOfYear = bucketIndex * dayStep + 1;

    // Convert bucketStartDayOfYear back to month and day
    int bucketMonth = 1;
    int remainingDays = bucketStartDayOfYear;
    for (int i = 0; i < 12; i++) {
        if (remainingDays <= daysInMonth[i]) {
            bucketMonth = i + 1;
            int bucketDay = remainingDays;
            // Construct the result
            return (long) year * 10000 + (long) bucketMonth * 100 + bucketDay;
        }
        remainingDays -= daysInMonth[i];
    }

    // This should not happen if dayOfYear is valid
    throw new IllegalArgumentException("Invalid day of year: " + dayOfYear);
}
