public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("key and props must not be null");
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Perform variable substitution: replace ${var} with the value of var from props
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < value.length()) {
        if (i + 1 < value.length() && value.charAt(i) == '$' && value.charAt(i + 1) == '{') {
            int end = value.indexOf('}', i + 2);
            if (end != -1) {
                String varName = value.substring(i + 2, end);
                String varValue = props.getProperty(varName);
                if (varValue != null) {
                    result.append(varValue);
                } else {
                    // If variable not found, keep the original ${varName}
                    result.append(value, i, end + 1);
                }
                i = end + 1;
            } else {
                // No closing brace found, append the rest as is
                result.append(value.substring(i));
                i = value.length();
            }
        } else {
            result.append(value.charAt(i));
            i++;
        }
    }
    return result.toString();
}
