public long readRawVarint64() throws IOException {
    int shift = 0;
    long result = 0;
    while (true) {
        byte b = read();
        if (b == -1) {
            throw new EOFException("Truncated varint");
        }
        result |= (long) (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
        if (shift >= 64) {
            throw new IOException("Malformed varint");
        }
    }
    return result;
}
