    private void pop(final String descriptor) {
        if (descriptor == null) {
            throw new IllegalArgumentException("Descriptor must not be null");
        }
        int count = 0;
        int i = 0;
        while (i < descriptor.length()) {
            char c = descriptor.charAt(i);
            if (c == '(') {
                i++;
                while (i < descriptor.length() && descriptor.charAt(i) != ')') {
                    count += popCountForType(descriptor, i);
                    i += popCountForType(descriptor, i);
                }
                if (i < descriptor.length() && descriptor.charAt(i) == ')') {
                    i++;
                }
                break;
            } else {
                count += popCountForType(descriptor, i);
                i += popCountForType(descriptor, i);
            }
        }
        for (int j = 0; j < count; j++) {
            if (outputFrameStack.isEmpty()) {
                throw new IllegalStateException("Output frame stack is empty, cannot pop " + count + " types");
            }
            outputFrameStack.pop();
        }
    }

    private int popCountForType(final String descriptor, final int index) {
        char c = descriptor.charAt(index);
        switch (c) {
            case 'B': // boolean
            case 'C': // char
            case 'D': // double
            case 'F': // float
            case 'I': // int
            case 'J': // long
            case 'S': // short
            case 'Z': // byte
                return 1;
            case 'L': // object reference
                int end = descriptor.indexOf(';', index);
                if (end == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
                }
                return 1;
            case '[': // array
                return 1;
            default:
                throw new IllegalArgumentException("Invalid type character in descriptor: " + c);
        }
    }
