        int i = 0;
        while (i < descriptor.length()) {
            char c = descriptor.charAt(i);
            if (c == 'L') {
                // Find the closing semicolon
                int end = descriptor.indexOf(';', i);
                if (end == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing semicolon");
                }
                count++;
                i = end + 1;
            } else if (c == '[') {
                // Array type, skip the brackets and process the element type
                i++;
            } else if (c == '(') {
                // Method descriptor, process the argument types
                i++;
                while (i < descriptor.length() && descriptor.charAt(i) != ')') {
                    char argC = descriptor.charAt(i);
                    if (argC == 'L') {
                        int end = descriptor.indexOf(';', i);
                        if (end == -1) {
                            throw new IllegalArgumentException("Invalid descriptor: missing semicolon");
                        }
                        count++;
                        i = end + 1;
                    } else if (argC == '[') {
                        i++;
                    } else {
                        // Primitive type
                        count++;
                        i++;
                    }
                }
                if (i >= descriptor.length()) {
                    throw new IllegalArgumentException("Invalid descriptor: missing closing parenthesis");
                }
                i++; // Skip the closing parenthesis
            } else {
                // Primitive type
                count++;
                i++;
            }
        }
