public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    // Normalize the base path: ensure it ends with a separator if it's not empty
    String normalizedPath = path;
    if (!normalizedPath.isEmpty() && !normalizedPath.endsWith("/")) {
        normalizedPath += "/";
    }

    // Handle the relative path
    String result = normalizedPath + relativePath;

    // Normalize the result: remove duplicate slashes and trailing slashes (unless it's a root)
    // We'll use a simple approach: split by "/" and rebuild, skipping empty segments
    String[] parts = result.split("/");
    StringBuilder sb = new StringBuilder();
    boolean isRoot = result.startsWith("/");

    if (isRoot) {
        sb.append("/");
    }

    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            // Remove the last segment if possible
            int lastSlash = sb.lastIndexOf("/");
            if (lastSlash > 0) {
                sb.setLength(lastSlash);
            } else if (lastSlash == 0) {
                // We're at root, can't go up
                sb.setLength(0);
            }
        } else {
            if (sb.length() > 0 && !sb.toString().endsWith("/")) {
                sb.append("/");
            }
            sb.append(part);
        }
    }

    // If the result is empty and we started with a root, return "/"
    if (sb.length() == 0 && isRoot) {
        return "/";
    }

    // If the result is empty and we didn't start with a root, return "."
    if (sb.length() == 0 && !isRoot) {
        return ".";
    }

    return sb.toString();
}

