public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        throw new IOException("File does not exist or is not a file: " + file);
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return result;
    }

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty() || line.startsWith("#")) {
                continue;
            }
            // Assuming the format is: timestamp,threadName,stackTrace
            // We need to parse the line and check if the timestamp falls within any of the time ranges
            String[] parts = line.split(",", 3);
            if (parts.length < 3) {
                continue;
            }
            try {
                long timestamp = Long.parseLong(parts[0].trim());
                String threadName = parts[1].trim();
                String stackTrace = parts[2].trim();

                // Check if the timestamp falls within any of the time ranges
                for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                    if (timeRange != null && timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                        ThreadSnapshot snapshot = new ThreadSnapshot();
                        snapshot.setTimestamp(timestamp);
                        snapshot.setThreadName(threadName);
                        snapshot.setStackTrace(stackTrace);
                        result.add(snapshot);
                        break; // Only add once, even if multiple ranges match
                    }
                }
            } catch (NumberFormatException e) {
                // Skip lines with invalid timestamp format
                continue;
            }
        }
    }
    return result;
}
